3	--
4	-- Fixes the INSERT failure on all 34 legacy tables from migration 0017.
5	-- Problem: app_id is NOT NULL but has no DEFAULT and no trigger — frontend
6	-- never passes app_id, so all INSERTs fail with "null value" constraint.
7	--
8	-- Solution:
9	-- 1. Add DEFAULT get_app_id('rankora') on app_id for all 34 tables
10	-- 2. Add BEFORE INSERT trigger as safety net (in case DEFAULT doesn't fire)
11	-- 3. Add app_id to the 2 remaining gap tables (rankora_platform_config,
12	--    email_ingest_logs)
13	-- ============================================================================
14	
15	
16	-- ────────────────────────────────────────────────────────────────────────────
17	-- PART 1: Shared trigger function — auto-populates app_id on INSERT
18	-- ────────────────────────────────────────────────────────────────────────────
19	
20	CREATE OR REPLACE FUNCTION set_rankora_app_id()
21	RETURNS trigger
22	LANGUAGE plpgsql AS $$
23	BEGIN
24	  IF NEW.app_id IS NULL THEN
25	    NEW.app_id := get_app_id('rankora');
26	  END IF;
27	  RETURN NEW;
28	END;
29	$$;
30	
